function tint(hex, a) {
  const x = hex.replace("#", "");
  const r = parseInt(x.slice(0, 2), 16), g = parseInt(x.slice(2, 4), 16), b = parseInt(x.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${a})`;
}

const TABLE_CENTER = { x: 228.5, y: 232.5 };
const HEAD_R = 20.25;
const SEATS = [
  { x: 103.191, y: 118.31  },
  { x: 229.311, y: 66.311  },
  { x: 348.311, y: 114.311 },
  { x: 398.311, y: 237.311 },
  { x: 348.311, y: 351.311 },
  { x: 234.311, y: 399.311 },
  { x: 117.311, y: 359.311 },
  { x: 63.311,  y: 242.311 },
].map((p) => {
  const dx = p.x - TABLE_CENTER.x, dy = p.y - TABLE_CENTER.y;
  const len = Math.hypot(dx, dy);
  const ux = dx / len, uy = dy / len;
  const lx = p.x + ux * 41, ly = p.y + uy * 41;
  const anchor = lx < TABLE_CENTER.x - 18 ? "end" : lx > TABLE_CENTER.x + 18 ? "start" : "middle";
  const baseline = uy < -0.6 ? "auto" : uy > 0.6 ? "hanging" : "middle";
  return { ...p, lx, ly, anchor, baseline };
});

