function TableFace({ seatsBranches, onPick, hovered, setHovered, reduce }) {
  return (
    <svg viewBox="-112 -72 692 612" style={S.faceSvg} role="group">
      <CouncilArt />
      {SEATS.map((seat, i) => {
        const branch = seatsBranches[i];
        if (!branch) return null;
        const isHot = hovered === branch.id;
        return (
          <g
            key={branch.id}
            tabIndex={0}
            role="button"
            aria-label={`Open ${branch.name} curriculum`}
            style={{ cursor: "pointer", outline: "none" }}
            onMouseEnter={() => setHovered(branch.id)}
            onMouseLeave={() => setHovered((h) => (h === branch.id ? null : h))}
            onFocus={() => setHovered(branch.id)}
            onBlur={() => setHovered((h) => (h === branch.id ? null : h))}
            onClick={() => onPick(branch)}
            onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onPick(branch); } }}
          >
            {}
            <circle
              cx={seat.x} cy={seat.y} r={HEAD_R}
              fill={branch.color}
              style={{
                transformBox: "fill-box", transformOrigin: "center",
                transform: isHot ? "scale(2.05)" : "scale(0.7)",
                opacity: isHot ? 0.4 : 0,
                transition: reduce ? "none" : "transform .35s cubic-bezier(.2,.8,.25,1), opacity .35s ease",
                pointerEvents: "none",
              }}
            />
            {}
            <circle
              cx={seat.x} cy={seat.y} r={HEAD_R}
              fill={branch.color}
              stroke={isHot ? C.white : tint("#ffffff", 0.55)}
              strokeWidth={isHot ? 2.4 : 1.4}
              style={{
                transformBox: "fill-box", transformOrigin: "center",
                transform: isHot ? "translateY(-3px)" : "none",
                filter: isHot ? `drop-shadow(0 0 9px ${tint(branch.color, 0.95)})` : "none",
                transition: reduce ? "none" : "transform .3s cubic-bezier(.2,.8,.25,1), filter .3s ease, stroke-width .2s ease",
              }}
            />
            {}
            <circle cx={seat.x - 5.5} cy={seat.y - 6} r={4.4} fill={tint("#ffffff", isHot ? 0.5 : 0.28)} style={{ pointerEvents: "none" }} />

            {}
            {(() => {
              const MAX = 18;
              const name = branch.name;
              let lines = [name];
              if (name.length > MAX) {
                const mid = Math.floor(name.length / 2);
                let best = -1, bestDist = Infinity;
                for (let i = 0; i < name.length; i++) {
                  if (name[i] === " ") {
                    const d = Math.abs(i - mid);
                    if (d < bestDist) { bestDist = d; best = i; }
                  }
                }
                if (best > 0) lines = [name.slice(0, best), name.slice(best + 1)];
              }
              const lineH = 16;
              const offsetY = lines.length > 1 ? -(lineH / 2) : 0;
              return (
                <text
                  x={seat.lx} y={seat.ly}
                  textAnchor={seat.anchor}
                  dominantBaseline={seat.baseline}
                  style={{
                    fontFamily: "'Inter', system-ui, sans-serif",
                    fontSize: 15,
                    fontWeight: isHot ? 800 : 700,
                    fill: isHot ? branch.color : C.ink,
                    letterSpacing: 0.2,
                    stroke: C.offWhite,
                    strokeWidth: 4,
                    paintOrder: "stroke",
                    strokeLinejoin: "round",
                    transition: reduce ? "none" : "fill .25s ease, font-weight .15s ease",
                    pointerEvents: "none",
                    userSelect: "none",
                  }}
                >
                  {lines.map((line, li) => (
                    <tspan key={li} x={seat.lx} dy={li === 0 ? offsetY : lineH}>{line}</tspan>
                  ))}
                </text>
              );
            })()}
          </g>
        );
      })}
    </svg>
  );
}

function CreditCard({ branch, year, onYear }) {
  const [credits, setCredits] = useState(null);
  const [loading, setLoading] = useState(false);

  /* Nothing is fetched — and nothing is shown — until a year is picked. */
  useEffect(() => {
    if (!year) { setCredits(null); setLoading(false); return; }
    let cancelled = false;
    setCredits(null);
    setLoading(true);
    api.curriculum(branch.id, null, { batchYear: year })
      .then((res) => { if (!cancelled && res.data?.credits) setCredits(res.data.credits); })
      .catch(() => null)
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [branch.id, year]);

  const rows = credits?.rows ?? [];
  const max  = rows.length ? Math.max(...rows.map((r) => r.credits)) : 0;

  return (
    <div style={{ ...S.creditCard, animation: "fadeUp .25s ease both" }}>
      <div style={S.ccHead}>
        <span style={{ ...S.ccDot, background: branch.color }} />
        <span style={S.ccBranch}>{branch.name}</span>
      </div>

      <div style={S.ccYearRow} role="tablist" aria-label="Batch year">
        {CARD_YEARS.map((y) => {
          const on = year === y;
          return (
            <button
              key={y}
              type="button"
              role="tab"
              aria-selected={on}
              data-on={String(on)}
              className="uc-cc-year"
              onClick={() => onYear(y)}
              style={{
                ...S.ccYearTab,
                ...(on ? {
                  borderColor: branch.color,
                  color: branch.color,
                  background: tint(branch.color, 0.1),
                  fontWeight: 800,
                } : {}),
              }}
            >
              {y}
            </button>
          );
        })}
      </div>

      {!year ? (
        <p style={S.ccHint}>Pick a batch year above to see the credit breakdown.</p>
      ) : loading ? (
        <p style={S.ccHint}>Loading credit breakdown…</p>
      ) : !rows.length ? (
        <p style={S.ccHint}>No credit breakdown published for the {year} batch yet.</p>
      ) : (
        <>
          <div style={S.ccTotalRow}>
            <span style={{ ...S.ccTotal, color: branch.color }}>{credits.total}</span>
            <span style={S.ccTotalLabel}>total credits to graduate</span>
          </div>
          <div style={S.ccRows}>
            {rows.map((r) => (
              <div key={r.label} style={S.ccRow}>
                <span style={S.ccLabel}>{r.label}</span>
                <div style={S.ccTrack}>
                  <div style={{ ...S.ccFill, width: `${(r.credits / max) * 100}%`, background: branch.color }} />
                </div>
                <span style={S.ccVal}>{r.credits}</span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function CouncilEmblem({ branches, onPick, reduce, big, onHover }) {
  const [side, setSide] = useState(0);
  const [hovered, setHovered] = useState(null);

  const front = branches.slice(0, 8);
  const back  = branches.slice(8, 16);

  useEffect(() => {
    if (!onHover) return;
    onHover(branches.find((b) => b.id === hovered) || null);
  }, [hovered, onHover, branches]);

  return (
    <div style={S.emblemWrap}>
      <div style={{ ...S.flipStage, width: big ? "min(740px, 54vw, 78vh)" : "min(540px, 92vw)" }}>
        <div style={{ ...S.flipInner, transform: `rotateY(${side * 180}deg)`, transition: reduce ? "none" : "transform .85s cubic-bezier(.65,.05,.2,1)" }}>
          <div style={{ ...S.flipFace }}>
            <TableFace seatsBranches={front} onPick={onPick} hovered={hovered} setHovered={setHovered} reduce={reduce} />
          </div>
          <div style={{ ...S.flipFace, ...S.flipBack }}>
            <TableFace seatsBranches={back} onPick={onPick} hovered={hovered} setHovered={setHovered} reduce={reduce} />
          </div>
        </div>
      </div>

      {}
      <div style={S.flipControls}>
        <span style={S.sideTag}>{side === 0 ? "Seats 1–8" : "Seats 9–16"}</span>
        <button
          style={S.flipBtn}
          onClick={() => { setHovered(null); setSide((s) => (s === 0 ? 1 : 0)); }}
          aria-label="Flip the table to the other eight branches"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" style={{ marginRight: 8 }} aria-hidden="true">
            <path d="M3 12a9 9 0 0 1 15.5-6.2M21 4v4h-4M21 12a9 9 0 0 1-15.5 6.2M3 20v-4h4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          Flip the table
        </button>
        <span aria-hidden="true" />
      </div>
    </div>
  );
}


/* GE specialisation options, as published in the compiled curriculum.
   Fintech and Open Specialisation only exist from the 2024 batch onwards; the
   batch tabs narrow themselves once a specialisation is picked. */
const GE_SPECIALISATIONS = [
  { code: "GE-AIR",  name: "AI and Robotics" },
  { code: "GE-MEC",  name: "Mechatronics" },
  { code: "GE-COM",  name: "Communication Technology" },
  { code: "GE-OPEN", name: "Open Specialisation" },
  { code: "GE-FIN",  name: "Fintech" },
];

function BranchCurriculum({ branch, onBack, reduce }) {
  const navigate = useNavigate();
  const mobile = useIsMobile();
  const [batch, setBatch]           = useState(null);
  const [batches, setBatches]       = useState(FALLBACK_BATCHES);
  const [semesters, setSemesters]   = useState([]);
  const [loading, setLoading]       = useState(true);
  const [geSpec, setGeSpec]         = useState(null);

  const isGE = branch.id === "GE";

  useEffect(() => {
    // GE: don't fetch until a specialisation has been chosen.
    if (isGE && !geSpec) { setLoading(false); setSemesters([]); return; }

    let cancelled = false;
    setLoading(true);
    setSemesters([]);

    const opts = {};
    if (isGE && geSpec) opts.specialisation = geSpec;
    if (batch) opts.batchYear = batch;

    api.curriculum(branch.id, null, opts).then((res) => {
      if (cancelled) return;
      const data = res.data;
      if (data) {
        setSemesters(data.semesters || []);
        if (data.batches?.length) {
          setBatches(data.batches);
          // Non-GE auto-selects the latest batch; GE waits for a pick.
          if (!isGE) setBatch((b) => b || data.batches[0]);
        } else if (!isGE) {
          setBatch((b) => b || FALLBACK_BATCHES[0]);
        }
      }
      setLoading(false);
    }).catch(() => { if (!cancelled) setLoading(false); });

    return () => { cancelled = true; };
  }, [branch.id, isGE, geSpec, batch]);

  /* semesterCredits counts a "choose 1" basket once and ignores rows the PDF
     left blank, so this matches the Total printed on each semester table. */
  const totalCredits = semesters.reduce((t, s) => t + semesterCredits(s), 0);
  const displayBatches = batches.length ? batches : FALLBACK_BATCHES;
  // GE requires an explicit batch pick; other branches default to the latest.
  const activeBatch    = isGE ? batch : (batch || displayBatches[0]);

  const mobileTab = {
    ...S.tab,
    padding: "8px 4px",
    minWidth: 0,
    flex: "1 1 0",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    textAlign: "center",
    borderRadius: 10,
    gap: 0,
  };

  return (
    <div style={{ ...S.branchPage, animation: reduce ? "none" : "fadeUp .4s ease both" }}>
      <div style={{ ...S.accentBar, background: branch.color }} />
      <div style={mobile
        ? { marginBottom: 20, display: "flex", flexDirection: "column", gap: 10, alignItems: "flex-start" }
        : S.branchHeader
      }>
        <button style={S.backBtn} onClick={onBack}>{mobile ? "←" : "← All branches"}</button>
        <div>
          <p style={{ ...S.eyebrow, color: branch.color }}>UGAC · IIT Mandi · Curriculum</p>
          <h1 style={{ ...S.branchH1, textAlign: "left" }}>{branch.name}</h1>
        </div>
      </div>

      {}
      <div style={mobile
        ? { display: "flex", flexDirection: "column", gap: 16, marginBottom: 18 }
        : S.controlRow
      }>
        {}
        {/* Step 1 (GE only): choose a specialisation before anything else */}
        {isGE && (
          <div style={S.controlGroup}>
            <span style={S.groupLabel}>
              {geSpec ? "Specialisation" : "Step 1 · Choose your specialisation"}
            </span>
            <div style={S.tabRow}>
              {GE_SPECIALISATIONS.map((sp) => {
                const on = geSpec === sp.code;
                return (
                  <button
                    key={sp.code}
                    onClick={() => { if (!on) { setGeSpec(sp.code); setBatch(null); } }}
                    style={{
                      ...S.tab,
                      ...(on ? { ...S.tabActive, borderColor: branch.color, color: branch.color } : {}),
                    }}
                  >
                    <span style={S.tabBig}>{sp.name}</span>
                    <span style={S.tabSmall}>{sp.code}</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Step 2: choose a batch year (GE waits until a specialisation is set) */}
        {(!isGE || geSpec) && (
          <div style={mobile
            ? { display: "flex", flexDirection: "column", gap: 6, width: "100%" }
            : S.controlGroup
          }>
            <span style={S.groupLabel}>{isGE ? "Step 2 · Choose your batch year" : "Batch"}</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "nowrap", width: "100%" }}>
              {displayBatches.map((b) => {
                const on = activeBatch === b;
                return (
                  <button
                    key={b}
                    onClick={() => setBatch(b)}
                    style={{
                      ...(mobile ? mobileTab : S.tab),
                      ...(on ? { ...S.tabActive, borderColor: branch.color, color: branch.color } : {}),
                    }}
                  >
                    <span style={S.tabBig}>{b}</span>
                    {!mobile && <span style={S.tabSmall}>entry</span>}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* Step 3: the curriculum. GE stays gated until spec + year are chosen. */}
      {isGE && !geSpec ? (
        <p style={S.ccHint}>Choose a specialisation above to begin.</p>
      ) : isGE && !batch ? (
        <p style={S.ccHint}>
          Now pick a batch year to view the{" "}
          {GE_SPECIALISATIONS.find((s) => s.code === geSpec)?.name} curriculum.
        </p>
      ) : (
        <>
          <div style={S.yearMeta}>
            <span>
              {isGE
                ? `${GE_SPECIALISATIONS.find((s) => s.code === geSpec)?.name} · ${activeBatch} batch`
                : `${activeBatch} batch`}
            </span>
            <span style={{ color: branch.color, fontWeight: 700 }}>{totalCredits} credits</span>
          </div>

          {loading ? (
            <div style={{ padding: "40px 0", textAlign: "center", color: C.textMuted, fontSize: 14, fontWeight: 600 }}>
              Loading curriculum…
            </div>
          ) : semesters.length === 0 ? (
            <div style={{ padding: "40px 0", textAlign: "center", color: C.textMuted, fontSize: 14 }}>
              No curriculum data available for this branch yet.
            </div>
          ) : semesters.map((sem) => {
            /* One column count, used by the basket banner's colSpan too. */
            const cols = 3 + (isGE ? 1 : 0) + (mobile ? 0 : 2);
            return (
              <div key={sem.num} style={S.semBlock}>
                <div style={S.semHeader}>
                  <span style={S.semNum}>Semester {sem.num}</span>
                  <span style={{ ...S.semCredits, color: branch.color }}>
                    {semesterCredits(sem)} credits
                  </span>
                </div>
                <div style={S.tableScroll}>
                  <table style={S.table}>
                    <thead>
                      <tr>
                        {!mobile && <th style={S.th}>Category</th>}
                        <th style={S.th}>Code</th>
                        <th style={{ ...S.th, textAlign: "left" }}>Course Title</th>
                        {isGE && <th style={S.th}>Specialisation</th>}
                        {!mobile && <th style={S.th}>L-T-P-C</th>}
                        <th style={S.th}>Credits</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sem.courses.map((c, i) => {
                        const group = c.choiceGroup || null;
                        /* Banner once per basket, above its first option. */
                        const opensGroup =
                          group && sem.courses[i - 1]?.choiceGroup?.id !== group.id;

                        return (
                          <Fragment key={`${sem.num}-${c.code || "row"}-${i}`}>
                            {opensGroup && (
                              <tr style={S.tr}>
                                <td colSpan={cols} style={S.groupBanner}>
                                  <span style={{ color: branch.color }}>{group.label}</span>
                                  {" · choose "}{group.choose}
                                  {group.credits != null && ` · ${group.credits} credits`}
                                </td>
                              </tr>
                            )}
                            <tr
                              style={{
                                ...S.tr,
                                cursor: c.id ? "pointer" : "default",
                                ...(group ? { background: tint(branch.color, 0.035) } : null),
                              }}
                              onClick={() => c.id && navigate(`/courses/${c.id}`)}
                              title={c.id ? "View course details" : undefined}
                            >
                              {!mobile && (
                                <td style={{ ...S.td, ...S.categoryCell }}>{c.category || "—"}</td>
                              )}
                              <td style={{ ...S.td, ...S.codeCell, color: branch.color }}>
                                {c.code || "—"}
                              </td>
                              <td style={{ ...S.td, fontWeight: 500 }}>
                                {c.title}
                                {c.isOptional && <span style={S.optionalTag}>optional</span>}
                              </td>
                              {isGE && (
                                <td style={{ ...S.td, ...S.codeCell, fontSize: 11, color: c.specialisation ? branch.color : C.textDim }}>
                                  {c.specialisation || "—"}
                                </td>
                              )}
                              {!mobile && (
                                <td style={{ ...S.td, ...S.ltpcCell }}>{c.ltpc || "—"}</td>
                              )}
                              {/* null credits means the PDF printed none — never show a 0. */}
                              <td style={{ ...S.td, ...S.creditsCell }}>
                                {c.credits == null ? "—" : c.credits}
                              </td>
                            </tr>
                          </Fragment>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            );
          })}
        </>
      )}
    </div>
  );
}

export default function CurriculumPage() {
  const navigate = useNavigate();
  const [active, setActive]             = useState(null);
  const [branches, setBranches]         = useState(FALLBACK_BRANCHES);
  const [reduce, setReduce]             = useState(false);
  const [isDesktop, setIsDesktop]       = useState(true);
  const [hoveredBranch, setHoveredBranch] = useState(null);
  const [cardBranch, setCardBranch]     = useState(null);
  const [year, setYear]                 = useState(null);

  /* The head clears `hovered` on mouseleave. Latch the last real branch so the
     card (and its year tabs) survives the trip from the table to the card. */
  useEffect(() => {
    if (hoveredBranch) setCardBranch(hoveredBranch);
  }, [hoveredBranch]);

  useEffect(() => {
    // BRANCH_META is authoritative for the 12 branches.
    // When /branches/ endpoint is ready, swap with api call here.
    setBranches(FALLBACK_BRANCHES);
  }, []);

  useEffect(() => {
    const m = window.matchMedia("(prefers-reduced-motion: reduce)");
    const apply = () => setReduce(m.matches);
    apply();
    m.addEventListener?.("change", apply);
    return () => m.removeEventListener?.("change", apply);
  }, []);

  useEffect(() => {
    const d = window.matchMedia("(min-width: 900px)");
    const apply = () => setIsDesktop(d.matches);
    apply();
    d.addEventListener?.("change", apply);
    return () => d.removeEventListener?.("change", apply);
  }, []);

  return (
    <div className="uc-curriculum" style={S.page}>

      {active ? (
        <BranchCurriculum branch={active} onBack={() => setActive(null)} reduce={reduce} />
      ) : (
        <div style={{ ...S.landing, animation: reduce ? "none" : "rise .5s ease both" }}>
          <button style={{ ...S.backBtn, marginBottom: 20 }} onClick={() => navigate("/")}>
            {isDesktop ? "← Back" : "←"}
          </button>

          {isDesktop ? (
            <div style={S.heroRow}>
              <div style={S.heroText}>
                <p style={S.eyebrow}>UGAC · IIT Mandi</p>
                <h1 style={S.pageH1}>Curriculum</h1>
                <p style={S.lede}>Sixteen branches, one table. Pick a seat to open its programme.</p>
                <div style={S.creditSlot}>
                  {cardBranch
                    ? <CreditCard branch={cardBranch} year={year} onYear={setYear} />
                    : <div style={S.creditPrompt}>Hover a branch on the table, then pick a batch year to see its credit breakdown.</div>}
                </div>
              </div>
              <div style={S.heroEmblem}>
                <CouncilEmblem branches={branches} onPick={setActive} onHover={setHoveredBranch} reduce={reduce} big />
              </div>
            </div>
          ) : (
            <div style={S.heroStack}>
              <div style={S.heroTextStack}>
                <p style={S.eyebrow}>UGAC · IIT Mandi</p>
                <h1 style={S.pageH1}>Curriculum</h1>
                <p style={S.lede}>Sixteen branches, one table. Pick a seat to open its programme.</p>
              </div>
              <CouncilEmblem branches={branches} onPick={setActive} reduce={reduce} />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

